            'CREATE TABLE document_charge ('
            . 'company_id UUID NOT NULL, '
            . 'document_id UUID NOT NULL, '
            . 'position SMALLINT NOT NULL, '
            . 'label TEXT NOT NULL, '
            . 'amount NUMERIC(19, 4) NOT NULL, '
            . 'PRIMARY KEY (company_id, document_id, position))',
